const fs = require('fs'), fsp = require('fs/promises'), path = require('path'), { pathToFileURL } = require('url');
const D = path.join(require('os').tmpdir(), 'm34-' + process.pid);
fs.rmSync(D, { recursive: true, force: true }); fs.mkdirSync(D);
const U = (p) => pathToFileURL(path.join(D, p));
const R = (l, f) => { try { const v = f(); console.log(l, JSON.stringify(v === undefined ? 'ok' : v)); } catch (e) { console.log(l, 'throws', e.code, e.name); } };
R('writeFileSync', () => fs.writeFileSync(U('a.txt'), 'hello'));
R('readFileSync', () => fs.readFileSync(U('a.txt'), 'utf8'));
R('appendFileSync', () => fs.appendFileSync(U('a.txt'), '!'));
R('existsSync', () => [fs.existsSync(U('a.txt')), fs.existsSync(U('no')), fs.existsSync(new URL('http://x/y')), fs.existsSync(new URL('file://host/x'))]);
R('statSync', () => fs.statSync(U('a.txt')).size);
R('lstatSync', () => fs.lstatSync(U('a.txt')).isFile());
R('accessSync', () => fs.accessSync(U('a.txt')));
R('mkdirSync', () => fs.mkdirSync(U('d/e'), { recursive: true }) !== undefined);
R('readdirSync', () => fs.readdirSync(U('.')).sort());
R('copyFileSync', () => fs.copyFileSync(U('a.txt'), U('b.txt')));
R('renameSync', () => fs.renameSync(U('b.txt'), U('c.txt')));
R('linkSync', () => fs.linkSync(U('c.txt'), U('h.txt')));
R('symlinkSync', () => fs.symlinkSync(U('c.txt'), U('s.txt')));
R('readlinkSync', () => path.basename(fs.readlinkSync(U('s.txt'))));
R('realpathSync', () => path.basename(fs.realpathSync(U('s.txt'))));
R('realpathSync.native', () => path.basename(fs.realpathSync.native(U('s.txt'))));
R('truncateSync', () => fs.truncateSync(U('c.txt'), 2));
R('chmodSync', () => fs.chmodSync(U('c.txt'), 0o600));
R('utimesSync', () => fs.utimesSync(U('c.txt'), 1000, 2000));
R('openSync', () => { const fd = fs.openSync(U('c.txt'), 'r'); fs.closeSync(fd); return typeof fd; });
R('cpSync', () => fs.cpSync(U('d'), U('d2'), { recursive: true }));
R('mkdtempSync', () => typeof fs.mkdtempSync(path.join(D, 'tmp-')));
R('opendirSync', () => { const d = fs.opendirSync(U('d')); const n = d.readSync().name; d.closeSync(); return n; });
R('unlinkSync', () => fs.unlinkSync(U('h.txt')));
R('rmdirSync', () => fs.rmdirSync(U('d2/e')));
R('rmSync', () => fs.rmSync(U('d2'), { recursive: true }));
R('watch-ish statSync bad scheme', () => fs.statSync(new URL('http://x/y')));
R('bad host', () => fs.readFileSync(new URL('file://host/x')));
R('bad path %2F', () => fs.readFileSync(new URL('file:///a%2Fb')));
R('string file: is a path', () => fs.existsSync('file:///etc/hosts'));
(async () => {
  const P = async (l, f) => { try { const v = await f(); console.log(l, JSON.stringify(v === undefined ? 'ok' : v)); } catch (e) { console.log(l, 'rejects', e.code, e.name); } };
  await P('p.readFile', () => fsp.readFile(U('a.txt'), 'utf8'));
  await P('p.writeFile', () => fsp.writeFile(U('p.txt'), 'x'));
  await P('p.stat', async () => (await fsp.stat(U('p.txt'))).size);
  await P('p.readdir', async () => (await fsp.readdir(U('d'))));
  await P('p.realpath', async () => path.basename(await fsp.realpath(U('s.txt'))));
  await P('p.open', async () => { const h = await fsp.open(U('p.txt')); await h.close(); return 'opened'; });
  await P('p.rm', () => fsp.rm(U('p.txt')));
  await P('p.access bad scheme', () => fsp.access(new URL('http://x/y')));
  await P('p.readFile bad host', () => fsp.readFile(new URL('file://host/x')));
  let sync = 'none'; try { const pr = fsp.stat(new URL('https://x/')); sync = 'returned ' + (pr instanceof Promise); pr.catch(() => {}); } catch (e) { sync = 'threw ' + e.code; }
  console.log('p.stat bad scheme is', sync);
  await new Promise((r) => fs.readFile(U('a.txt'), 'utf8', (e, d) => { console.log('cb.readFile', e?.code, d); r(); }));
  try { fs.stat(new URL('http://x/y'), () => console.log('cb.stat bad called back')); } catch (e) { console.log('cb.stat bad throws', e.code); }
  await new Promise((r) => fs.exists(U('a.txt'), (x) => { console.log('cb.exists', x); r(); }));
  await new Promise((r) => fs.exists(new URL('http://x/y'), (x) => { console.log('cb.exists bad', x); r(); }));
  await new Promise((r) => fs.realpath.native(U('s.txt'), (e, p) => { console.log('cb.realpath.native', e?.code, path.basename(p ?? '')); r(); }));
  await new Promise((r) => { let s = ''; fs.createReadStream(U('a.txt'), 'utf8').on('data', (c) => (s += typeof c + ':' + c)).on('end', () => { console.log('rs url utf8', s); r(); }); });
  await new Promise((r) => { const w = fs.createWriteStream(U('w.txt'), 'utf8'); w.end('wdata', () => { console.log('ws url', fs.readFileSync(U('w.txt'), 'utf8')); r(); }); });
  fs.rmSync(D, { recursive: true, force: true });
})();
